package gg.jte.generated.ondemand;
public final class JteindexGenerated {
	public static final String JTE_NAME = "index.jte";
	public static final int[] JTE_LINE_INFO = {0,0,0,0,112,112,112,112,112,112,112,153,153,153,0,1,1,1,1};
	public static void render(gg.jte.html.HtmlTemplateOutput jteOutput, gg.jte.html.HtmlInterceptor jteHtmlInterceptor, String text, String time) {
		jteOutput.writeContent("<!DOCTYPE html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Простой чат</title>\n<style>\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body {\n    font-family: Arial, sans-serif;\n    background: #f0f2f5;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 100vh;\n  }\n  .chat {\n    width: 100%;\n    max-width: 480px;\n    height: 600px;\n    background: #fff;\n    border-radius: 12px;\n    box-shadow: 0 4px 20px rgba(0,0,0,0.1);\n    display: flex;\n    flex-direction: column;\n    overflow: hidden;\n  }\n  .chat-header {\n    background: #4a76a8;\n    color: #fff;\n    padding: 15px 20px;\n    font-size: 18px;\n    font-weight: bold;\n  }\n  .messages {\n    flex: 1;\n    padding: 15px;\n    overflow-y: auto;\n    display: flex;\n    flex-direction: column;\n    gap: 10px;\n    background: #e5ddd5;\n  }\n  .msg {\n    max-width: 75%;\n    padding: 8px 12px;\n    border-radius: 10px;\n    font-size: 14px;\n    line-height: 1.4;\n    word-wrap: break-word;\n    animation: appear 0.2s ease;\n  }\n  @keyframes appear {\n    from { opacity: 0; transform: translateY(5px); }\n    to { opacity: 1; transform: translateY(0); }\n  }\n  .msg.me {\n    align-self: flex-end;\n    background: #dcf8c6;\n    border-bottom-right-radius: 2px;\n  }\n  .msg.other {\n    align-self: flex-start;\n    background: #fff;\n    border-bottom-left-radius: 2px;\n  }\n  .msg .time {\n    display: block;\n    font-size: 11px;\n    color: #888;\n    text-align: right;\n    margin-top: 4px;\n  }\n  .input-area {\n    display: flex;\n    padding: 10px;\n    background: #f0f0f0;\n    border-top: 1px solid #ddd;\n  }\n  .input-area input {\n    flex: 1;\n    padding: 10px 14px;\n    border: 1px solid #ccc;\n    border-radius: 20px;\n    outline: none;\n    font-size: 14px;\n  }\n  .input-area input:focus {\n    border-color: #4a76a8;\n  }\n  .input-area button {\n    margin-left: 8px;\n    padding: 10px 18px;\n    background: #4a76a8;\n    color: #fff;\n    border: none;\n    border-radius: 20px;\n    cursor: pointer;\n    font-size: 14px;\n  }\n  .input-area button:hover {\n    background: #3b5f87;\n  }\n</style>\n</head>\n<body>\n\n<div class=\"chat\">\n  <div class=\"chat-header\">Chat</div>\n  <div class=\"messages\" id=\"messages\">\n    <div class=\"msg other\">");
		jteOutput.setContext("div", null);
		jteOutput.writeUserContent(text);
		jteOutput.writeContent("<span class=\"time\">");
		jteOutput.setContext("span", null);
		jteOutput.writeUserContent(time);
		jteOutput.writeContent("</span></div>\n  </div>\n  <div class=\"input-area\">\n    <input type=\"text\" id=\"input\" placeholder=\"Enter message...\" autocomplete=\"off\">\n    <button onclick=\"sendMessage()\">Send</button>\n  </div>\n</div>\n\n<script>\n  const messages = document.getElementById('messages');\n  const input = document.getElementById('input');\n\n  function sendMessage() {\n    const text = input.value.trim();\n    if (!text) return;\n\n    const now = new Date();\n    const time = now.getHours().toString().padStart(2, '0') + ':' +\n                 now.getMinutes().toString().padStart(2, '0');\n\n    const msg = document.createElement('div');\n    msg.className = 'msg me';\n    msg.innerHTML = escapeHtml(text) + '<span class=\"time\">' + time + '</span>';\n    messages.appendChild(msg);\n\n    input.value = '';\n    messages.scrollTop = messages.scrollHeight;\n  }\n\n  input.addEventListener('keydown', e => {\n    if (e.key === 'Enter') sendMessage();\n  });\n\n  function escapeHtml(str) {\n    return str.replace(/[&<>\"']/g, c => ({\n      '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'\n    })[c]);\n  }\n</script>\n\n</body>\n</html>");
	}
	public static void renderMap(gg.jte.html.HtmlTemplateOutput jteOutput, gg.jte.html.HtmlInterceptor jteHtmlInterceptor, java.util.Map<String, Object> params) {
		String text = (String)params.get("text");
		String time = (String)params.get("time");
		render(jteOutput, jteHtmlInterceptor, text, time);
	}
}
